+
+class GuiceInitSpec extends RatpackGroovyDslSpec {
+
+  @com.google.inject.Singleton
+  static class Thing {
+    final List<String> strings = []
+  }
+
+  static class ThingInit implements Runnable {
+    final Thing thing
+
+    @Inject
+    ThingInit(Thing thing) {
+      this.thing = thing
